export const c12EngV3HtmlOverview = "\n<style>\n  p, li, div:not(.table-container):not(.table-responsive):not(.pt-scroll-wrapper):not(.mcq-option) {\n    text-align: justify !important;\n  }\n  h1, h2, h3, h4, h5, h6 { text-align: left; }\n  .text-center { text-align: center !important; }\n  .text-left { text-align: left !important; }\n</style>\n\n<div style=\"font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; line-height: 1.8; color: #E2E8F0; max-width: 950px; margin: 0 auto; padding: 12px; font-size: 15.5px;\">\n\n  <!-- Chapter Header Badge -->\n  <div style=\"background: linear-gradient(135deg, rgba(38, 198, 218, 0.22), rgba(0, 172, 193, 0.1)); border: 1.5px solid #26C6DA; border-radius: 12px; padding: 20px; margin-bottom: 25px; box-shadow: 0 4px 22px rgba(38, 198, 218, 0.15);\">\n    <div style=\"display: flex; align-items: center; gap: 10px; margin-bottom: 8px;\">\n      <span style=\"background: #26C6DA; color: #000; font-size: 12px; font-weight: 800; padding: 4px 10px; border-radius: 6px; letter-spacing: 0.5px;\">VISTAS &bull; CHAPTER 3</span>\n      <span style=\"color: #94A3B8; font-size: 13.5px; font-weight: 600;\">CLASS XII ENGLISH CORE (SUPPLEMENTARY READER)</span>\n    </div>\n    <h1 style=\"color: #FFFFFF; font-size: 26px; font-weight: 900; margin: 0 0 6px 0; letter-spacing: -0.5px;\">Journey to the End of the Earth</h1>\n    <p style=\"color: #CBD5E1; font-size: 15px; margin: 0; font-style: italic;\">\n      By Tishani Doshi (b. 1975, India) &mdash; Geological Deep Time, Ecological Fragility &amp; The Cryosphere Warning\n    </p>\n  </div>\n\n  <!-- Quick Glossary & Chapter Dossier Card -->\n  <div style=\"background: rgba(15, 23, 42, 0.92); border: 1.5px solid rgba(38, 198, 218, 0.4); border-radius: 10px; padding: 18px 20px; margin-bottom: 25px; box-shadow: 0 4px 20px rgba(0,0,0,0.35);\">\n    <h3 style=\"color: #26C6DA; font-size: 18px; margin: 0 0 12px 0; display: flex; align-items: center; gap: 8px;\">\n      <span>📖</span> Quick Glossary &amp; Chapter Dossier: Journey to the End of the Earth\n    </h3>\n    <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; font-size: 14px; color: #CBD5E1;\">\n      <div><b style=\"color: #26C6DA;\">Author:</b> Tishani Doshi (Indian poet, novelist &amp; dancer)</div>\n      <div><b style=\"color: #26C6DA;\">Genre:</b> Environmental Travelogue / Ecological Non-Fiction</div>\n      <div><b style=\"color: #26C6DA;\">Setting:</b> Antarctica &mdash; The Coldest, Driest, Windiest Continent</div>\n      <div><b style=\"color: #26C6DA;\">Research Vessel:</b> <i>Akademik Shokalskiy</i> (Russian Icebreaker)</div>\n      <div><b style=\"color: #26C6DA;\">Program:</b> 'Students on Ice' (Founded by Canadian educator Geoff Green)</div>\n      <div><b style=\"color: #26C6DA;\">Core Geological Motif:</b> Gondwana Supercontinent (650 Million Years Ago)</div>\n      <div><b style=\"color: #26C6DA;\">Microscopic Hero:</b> Phytoplankton (Single-celled marine photosynthetic algae)</div>\n      <div><b style=\"color: #26C6DA;\">Golden Maxim:</b> <i>\"Take care of the small things and the big things will take care of themselves.\"</i></div>\n    </div>\n  </div>\n\n  <!-- Section 1: Executive Summary & Context -->\n  <h2 style=\"color: #26C6DA; font-size: 20px; font-weight: 800; border-bottom: 2px solid #26C6DA; padding-bottom: 6px; margin: 28px 0 16px 0;\">\n    1. Executive Summary &amp; Authorial Vision\n  </h2>\n  <p>\n    <b style=\"color: #26C6DA;\">'Journey to the End of the Earth'</b> by renowned contemporary Indian poet and writer <b style=\"color: #26C6DA;\">Tishani Doshi</b> is an evocative first-person travelogue and ecological wake-up call recounting her journey to Antarctica aboard the Russian research vessel <b style=\"color: #26C6DA;\">Akademik Shokalskiy</b>. Participating in Canadian educator <b style=\"color: #26C6DA;\">Geoff Green's</b> pioneering <b style=\"color: #26C6DA;\">'Students on Ice'</b> program, Doshi accompanies high school students to the pristine southern polar ice cap to bear witness to the planet's ecological past, present, and imperiled future.\n  </p>\n  <p>\n    Antarctica, storing nearly ninety percent of Earth's total ice volume, devoid of human settlements, trees, or billboards, is the world's most immaculate natural laboratory. Through the lens of geological deep time&mdash;tracing the fragmentation of the ancient supercontinent <b style=\"color: #26C6DA;\">Gondwana</b> into modern continents&mdash;Doshi dramatizes how human civilization, having existed for a mere twelve thousand seconds on the cosmic clock, has recklessly destabilized the biosphere through global warming and carbon emissions. By examining the collapse of polar ice shelves and the vital role of microscopic <b style=\"color: #26C6DA;\">phytoplankton</b>, the text urges humanity to respect the delicate balance of nature before irreversible climatic catastrophe engulfs our shared home.\n  </p>\n\n  <!-- Section 2: Chronological Narrative Architecture -->\n  <h2 style=\"color: #26C6DA; font-size: 20px; font-weight: 800; border-bottom: 2px solid #26C6DA; padding-bottom: 6px; margin: 30px 0 16px 0;\">\n    2. Chronological &amp; Thematic Narrative Architecture\n  </h2>\n\n  <h3 style=\"color: #26C6DA; font-size: 17px; margin-top: 22px;\">(i) The Arduous Journey to the Southernmost Tip</h3>\n  <p>\n    The expedition commenced at <b style=\"color: #26C6DA;\">13.09 degrees North</b> of the Equator in Madras (Chennai). The voyage demanded traveling across <b style=\"color: #26C6DA;\">nine time zones</b>, crossing <b style=\"color: #26C6DA;\">six checkpoints</b>, navigating <b style=\"color: #26C6DA;\">three bodies of water</b>, and traversing as many distinct ecospheres. The journey involved over <b style=\"color: #26C6DA;\">one hundred hours</b> of continuous travel combining car, airplane, and the Russian ice-strengthened vessel <i>Akademik Shokalskiy</i>.\n  </p>\n  <p>\n    Upon setting foot on the white continent, Doshi experienced profound relief followed immediately by immense wonder&mdash;wonder at Antarctica's vastness, its blinding white horizon, its deafening silence, and the baffling geological realization that India and Antarctica were once part of the very same contiguous landmass.\n  </p>\n\n  <h3 style=\"color: #26C6DA; font-size: 17px; margin-top: 22px;\">(ii) Gondwana: Deep Geological History</h3>\n  <p>\n    Six hundred and fifty million years ago, a giant amalgamated southern supercontinent known as <b style=\"color: #26C6DA;\">Gondwana</b> existed, centered roughly around present-day Antarctica. The climate was warm and tropical, supporting an immense variety of flora and fauna. Humans had not yet evolved on the global stage.\n  </p>\n  <p>\n    For 500 million years Gondwana thrived, but around the time the dinosaurs were wiped out and the age of mammals began, the landmass fractured into separate nations, shaping the modern globe. India broke free and drifted northward, crashing into Asia to buckle its crust and heave up the Himalayas. South America drifted away to join North America, opening the <b style=\"color: #26C6DA;\">Drake Passage</b> to unleash a freezing, circumpolar ocean current that left Antarctica desolate, frigid, and eternally locked in ice at the bottom of the world.\n  </p>\n\n  <h3 style=\"color: #26C6DA; font-size: 17px; margin-top: 22px;\">(iii) Human Impact: A Microsecond on the Cosmic Clock</h3>\n  <p>\n    Human civilizations have inhabited Earth for a mere twelve thousand years&mdash;barely a few seconds on the geological clock. Yet in this brief span, human population growth, unchecked urbanization, burning of fossil fuels, and deforestation have forged a suffocating blanket of <b style=\"color: #26C6DA;\">carbon dioxide</b> around the globe, triggering global temperature increases.\n  </p>\n  <p>\n    Antarctica, devoid of human habitation, remains the purest barometer of climate change. Its pristine ice sheet traps half-million-year-old carbon records. As global temperatures surge, Antarctic ice shelves are fracturing, retreating, and calving into the sea, threatening catastrophic rises in global sea levels.\n  </p>\n\n  <h3 style=\"color: #26C6DA; font-size: 17px; margin-top: 22px;\">(iv) 'Students on Ice': Educating Future Policy Makers</h3>\n  <p>\n    Doshi participated in <b style=\"color: #26C6DA;\">Geoff Green's 'Students on Ice'</b> initiative, which takes high school students to the ends of the earth to provide them with life-changing educational experiences. Green previously ferried wealthy celebrities and curious tourists who offered nothing back to the planet. Recognizing that youth are the future policy-makers, Green shifted focus to teenagers who possess the energy, curiosity, and idealism to absorb, act, and champion global environmental reform.\n  </p>\n\n  <h3 style=\"color: #26C6DA; font-size: 17px; margin-top: 22px;\">(v) Phytoplankton &amp; The Ecological Golden Rule</h3>\n  <p>\n    In Antarctica's Southern Ocean, single-celled microscopic plants called <b style=\"color: #26C6DA;\">phytoplankton</b> nourish and sustain the entire marine food web. These microscopic grasses of the sea assimilate carbon and synthesize organic compounds through photosynthesis.\n  </p>\n  <p>\n    Scientists warn that further depletion of the Antarctic ozone layer will disrupt phytoplankton photosynthesis, devastating marine birds, seals, whales, and the global carbon cycle. This microscopic reality embodies the chapter's profound ecological parable: <b style=\"color: #26C6DA;\">\"Take care of the small things and the big things will fall into place.\"</b>\n  </p>\n\n  <h3 style=\"color: #26C6DA; font-size: 17px; margin-top: 22px;\">(vi) Walking on the Ocean &amp; Epiphany</h3>\n  <p>\n    The climax of the journey occurs when the <i>Akademik Shokalskiy</i> wedges herself into a thick wedge of white ice between the Antarctic Peninsula and Tadpole Island. The captain orders all fifty-two passengers to disembark and walk across the frozen ocean.\n  </p>\n  <p>\n    Walking upon a metre-thick ice sheet with 180 metres of living, breathing salt water underneath, Doshi watches Crabeater seals stretching and sunning themselves on ice floes like stray dogs under a banyan tree. Standing at the end of the earth under the midnight sun, Doshi reflects on the interconnectedness of all life and marvels whether Antarctica will ever revert to the warm paradise it once was&mdash;and whether humanity will even survive to see it.\n  </p>\n\n  <!-- Section 3: Key Figures & Perspectives -->\n  <h2 style=\"color: #26C6DA; font-size: 20px; font-weight: 800; border-bottom: 2px solid #26C6DA; padding-bottom: 6px; margin: 30px 0 16px 0;\">\n    3. Key Figures &amp; Environmental Perspectives\n  </h2>\n\n  <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 16px; margin-bottom: 25px;\">\n    \n    <!-- Tishani Doshi -->\n    <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(38, 198, 218, 0.3); border-radius: 8px; padding: 16px;\">\n      <h3 style=\"color: #26C6DA; font-size: 17px; margin: 0 0 8px 0;\">1. Tishani Doshi (The Perceptive Observer)</h3>\n      <p style=\"font-size: 14px; margin: 0; color: #CBD5E1;\">\n        A south Indian poet and traveler originating from sun-drenched Madras. Her journey to freezing Antarctica serves as an intellectual and spiritual awakening. She observes both grand geological phenomena and microscopic oceanic organisms, articulating humanity's urgent responsibility toward our fragile biosphere.\n      </p>\n    </div>\n\n    <!-- Geoff Green -->\n    <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(38, 198, 218, 0.3); border-radius: 8px; padding: 16px;\">\n      <h3 style=\"color: #26C6DA; font-size: 17px; margin: 0 0 8px 0;\">2. Geoff Green (The Visionary Educator)</h3>\n      <p style=\"font-size: 14px; margin: 0; color: #CBD5E1;\">\n        A Canadian expedition leader who grew disillusioned with guiding rich celebrities and passive retirees. He established 'Students on Ice' to offer impressionable high school students firsthand exposure to climate reality, cultivating the next generation of informed planetary custodians and leaders.\n      </p>\n    </div>\n\n    <!-- Phytoplankton -->\n    <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(38, 198, 218, 0.3); border-radius: 8px; padding: 16px;\">\n      <h3 style=\"color: #26C6DA; font-size: 17px; margin: 0 0 8px 0;\">3. Phytoplankton (The Microscopic Linchpin)</h3>\n      <p style=\"font-size: 14px; margin: 0; color: #CBD5E1;\">\n        Microscopic single-celled plants that form the foundation of the Southern Ocean's marine ecosystem. By assimilating carbon and generating oxygen via photosynthesis, they sustain all higher trophic levels, proving that global survival depends upon protecting microscopic life forms.\n      </p>\n    </div>\n\n  </div>\n\n  <!-- Section 4: Literary & Rhetorical Devices Master Table -->\n  <h2 style=\"color: #26C6DA; font-size: 20px; font-weight: 800; border-bottom: 2px solid #26C6DA; padding-bottom: 6px; margin: 30px 0 16px 0;\">\n    4. Literary &amp; Rhetorical Devices Master Table\n  </h2>\n  <div style=\"overflow-x: auto; margin-bottom: 25px;\">\n    <table style=\"width: 100%; border-collapse: collapse; font-size: 14.5px; text-align: left; background: rgba(15, 23, 42, 0.9); border-radius: 8px; overflow: hidden;\">\n      <thead>\n        <tr style=\"background: rgba(38, 198, 218, 0.25); color: #FFFFFF; border-bottom: 2px solid #26C6DA;\">\n          <th style=\"padding: 12px 14px;\">Literary Device</th>\n          <th style=\"padding: 12px 14px;\">Textual Quote / Example</th>\n          <th style=\"padding: 12px 14px;\">Literary &amp; Thematic Effect</th>\n        </tr>\n      </thead>\n      <tbody>\n        <tr style=\"border-bottom: 1px solid rgba(255,255,255,0.08);\">\n          <td style=\"padding: 12px 14px; font-weight: bold; color: #26C6DA;\">Vivid Simile</td>\n          <td style=\"padding: 12px 14px;\">\"Crabeater seals were stretching and sunning themselves on ice floes much like you'd see stray dogs will do under the penumbra of a banyan tree.\"</td>\n          <td style=\"padding: 12px 14px; color: #CBD5E1;\">Bridges exotic polar wildlife with familiar Indian rustic imagery, evoking a startling sense of planetary unity.</td>\n        </tr>\n        <tr style=\"border-bottom: 1px solid rgba(255,255,255,0.08);\">\n          <td style=\"padding: 12px 14px; font-weight: bold; color: #26C6DA;\">Cosmic Contrast</td>\n          <td style=\"padding: 12px 14px;\">Human civilization (12,000 years) vs. Geological time (4.5 billion years / Gondwana 650 million years).</td>\n          <td style=\"padding: 12px 14px; color: #CBD5E1;\">Exposes the profound hubris and recklessness of humanity in destroying a planet that evolved over billions of years.</td>\n        </tr>\n        <tr style=\"border-bottom: 1px solid rgba(255,255,255,0.08);\">\n          <td style=\"padding: 12px 14px; font-weight: bold; color: #26C6DA;\">Metaphor &amp; Symbolism</td>\n          <td style=\"padding: 12px 14px;\">Antarctica as Earth's pristine climate barometer and living geological time capsule.</td>\n          <td style=\"padding: 12px 14px; color: #CBD5E1;\">Positions the frozen continent not as a wasteland, but as the essential key to understanding humanity's survival.</td>\n        </tr>\n        <tr style=\"border-bottom: 1px solid rgba(255,255,255,0.08);\">\n          <td style=\"padding: 12px 14px; font-weight: bold; color: #26C6DA;\">Aphoristic Wisdom</td>\n          <td style=\"padding: 12px 14px;\">\"Take care of the small things and the big things will fall into place.\"</td>\n          <td style=\"padding: 12px 14px; color: #CBD5E1;\">Encapsulates ecological interdependence; protecting microscopic phytoplankton preserves global marine ecology.</td>\n        </tr>\n        <tr style=\"border-bottom: 1px solid rgba(255,255,255,0.08);\">\n          <td style=\"padding: 12px 14px; font-weight: bold; color: #26C6DA;\">Sensory Deprivation &amp; Immensity</td>\n          <td style=\"padding: 12px 14px;\">\"A giant ping-pong ball devoid of any human markers &mdash; no trees, billboards, buildings.\"</td>\n          <td style=\"padding: 12px 14px; color: #CBD5E1;\">Forces the human mind to lose all earthly perspective of time and space, instilling reverence and awe.</td>\n        </tr>\n      </tbody>\n    </table>\n  </div>\n\n  <!-- Section 5: Board Exam Strategy & High-Scoring Tips Box -->\n  <div style=\"background: rgba(15, 23, 42, 0.92); border-left: 5px solid #26C6DA; border-radius: 8px; padding: 18px 20px; margin-bottom: 25px; box-shadow: 0 4px 20px rgba(0,0,0,0.3);\">\n    <h3 style=\"color: #26C6DA; font-size: 18px; margin: 0 0 10px 0; display: flex; align-items: center; gap: 8px;\">\n      <span>🎯</span> Board Examination Master Tips: Scoring 100% in Antarctica\n    </h3>\n    <ul style=\"color: #CBD5E1; font-size: 14.5px; padding-left: 20px; margin: 0; line-height: 1.8;\">\n      <li><b style=\"color: #26C6DA;\">Quote Geoff Green's Rationale:</b> When asked why high school students were taken instead of celebrities, explain that teenagers are at an age where they are ready to <b style=\"color: #26C6DA;\">absorb, learn, and act</b>.</li>\n      <li><b style=\"color: #26C6DA;\">Explain Gondwana &amp; Drake Passage:</b> Clearly mention that Gondwana existed 650 million years ago, centered around Antarctica, and the opening of the <b style=\"color: #26C6DA;\">Drake Passage</b> initiated the cold circumpolar current.</li>\n      <li><b style=\"color: #26C6DA;\">Highlight Phytoplankton:</b> In ecological questions, always explain that phytoplankton are single-celled marine grasses that carry out photosynthesis, underpinning the entire Southern Ocean food web.</li>\n    </ul>\n  </div>\n\n</div>\n";

export const c12EngV3HtmlSolutions = "\n<style>\n  p, li, div:not(.table-container):not(.table-responsive):not(.pt-scroll-wrapper):not(.mcq-option) {\n    text-align: justify !important;\n  }\n  h1, h2, h3, h4, h5, h6 { text-align: left; }\n  .text-center { text-align: center !important; }\n  .text-left { text-align: left !important; }\n</style>\n\n<div style=\"font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; line-height: 1.8; color: #E2E8F0; max-width: 950px; margin: 0 auto; padding: 12px; font-size: 15.5px;\">\n\n  <!-- Section Header Badge -->\n  <div style=\"background: linear-gradient(135deg, rgba(38, 198, 218, 0.22), rgba(0, 172, 193, 0.1)); border-left: 5px solid #26C6DA; padding: 16px 20px; border-radius: 8px; margin-bottom: 25px;\">\n    <h2 style=\"color: #26C6DA; font-weight: 900; margin: 0 0 4px 0; font-size: 21px;\">\n      BOARD EXAMINATION QUESTIONS &amp; MODEL ANSWERS\n    </h2>\n    <span style=\"color: #94A3B8; font-size: 14px; font-weight: 600;\">Standardized to CBSE &amp; JKBOSE Class XII English Core Blueprint &bull; Theme Color Standardized</span>\n  </div>\n\n  <!-- SECTION A: EXTRACT-BASED QUESTIONS -->\n  <h2 style=\"color: #26C6DA; font-size: 20px; font-weight: 800; border-bottom: 2px solid #26C6DA; padding-bottom: 6px; margin: 26px 0 16px 0;\">\n    SECTION A: Extract-Based Objective Questions (1 Mark Each)\n  </h2>\n\n  <!-- Extract 1 -->\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(38, 198, 218, 0.3); border-radius: 8px; padding: 16px; margin-bottom: 20px; border-left: 4px solid #26C6DA;\">\n    <p style=\"color: #94A3B8; font-style: italic; margin-top: 0; line-height: 1.7;\">\n      <b style=\"color: #26C6DA;\">Read the extract given below and answer the questions that follow:</b><br/>\n      \"Six hundred and fifty million years ago, a giant amalgamated southern supercontinent &mdash; Gondwana &mdash; did indeed exist, centred roughly around the present-day Antarctica. Things were quite different then: humans hadn't arrived on the global scene, and the climate was much warmer, hosting a huge variety of flora and fauna.\"\n    </p>\n    \n    <p>\n      <b style=\"color: #26C6DA; font-size: 15px;\">Q1: What supercontinent existed 650 million years ago, and where was it centred?</b><br/>\n      <span style=\"color: #26C6DA; font-weight: bold;\">✓ Answer:</span> <b style=\"color: #26C6DA;\">Gondwana</b> existed 650 million years ago, centred roughly around present-day Antarctica.\n    </p>\n\n    <p>\n      <b style=\"color: #26C6DA; font-size: 15px;\">Q2: How did the climatic conditions of Gondwana contrast with present-day Antarctica?</b><br/>\n      <span style=\"color: #26C6DA; font-weight: bold;\">✓ Answer:</span> Gondwana possessed a warm, tropical climate supporting diverse flora and fauna, whereas Antarctica is now freezing and desolate.\n    </p>\n\n    <p>\n      <b style=\"color: #26C6DA; font-size: 15px;\">Q3: Were human beings in existence during the era of Gondwana?</b><br/>\n      <span style=\"color: #26C6DA; font-weight: bold;\">✓ Answer:</span> No, humans had not yet arrived on the global evolutionary scene.\n    </p>\n\n    <p>\n      <b style=\"color: #26C6DA; font-size: 15px;\">Q4: How long did the Gondwana supercontinent thrive before fracturing into continents?</b><br/>\n      <span style=\"color: #26C6DA; font-weight: bold;\">✓ Answer:</span> Gondwana thrived for roughly <b style=\"color: #26C6DA;\">500 million years</b>.\n    </p>\n  </div>\n\n  <!-- Extract 2 -->\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(38, 198, 218, 0.3); border-radius: 8px; padding: 16px; margin-bottom: 20px; border-left: 4px solid #26C6DA;\">\n    <p style=\"color: #94A3B8; font-style: italic; margin-top: 0; line-height: 1.7;\">\n      <b style=\"color: #26C6DA;\">Read the extract given below and answer the questions that follow:</b><br/>\n      \"Human civilisations have been around for a paltry 12,000 years &mdash; barely a few seconds on the geological clock. In that short amount of time, we've managed to create quite a ruckus, etching our dominance over nature with our villages, towns, cities, megacities.\"\n    </p>\n    \n    <p>\n      <b style=\"color: #26C6DA; font-size: 15px;\">Q5: How long have human civilisations existed compared to the geological clock?</b><br/>\n      <span style=\"color: #26C6DA; font-weight: bold;\">✓ Answer:</span> Human civilisations have existed for a paltry <b style=\"color: #26C6DA;\">12,000 years</b>, barely a few seconds on the cosmic clock.\n    </p>\n\n    <p>\n      <b style=\"color: #26C6DA; font-size: 15px;\">Q6: What does the phrase 'create quite a ruckus' signify in the context of human activity?</b><br/>\n      <span style=\"color: #26C6DA; font-weight: bold;\">✓ Answer:</span> It signifies the widespread environmental disruption, pollution, and rapid deforestation caused by rampant urbanization.\n    </p>\n\n    <p>\n      <b style=\"color: #26C6DA; font-size: 15px;\">Q7: What has blanketed the earth as a consequence of unbridled burning of fossil fuels?</b><br/>\n      <span style=\"color: #26C6DA; font-weight: bold;\">✓ Answer:</span> A suffocating blanket of <b style=\"color: #26C6DA;\">carbon dioxide</b>, triggering unprecedented global warming.\n    </p>\n\n    <p>\n      <b style=\"color: #26C6DA; font-size: 15px;\">Q8: Why is Antarctica the ideal venue to study human impact on the planet?</b><br/>\n      <span style=\"color: #26C6DA; font-weight: bold;\">✓ Answer:</span> Because it remains untouched by permanent human settlements, preserving pristine ancient ice cores and clear climate records.\n    </p>\n  </div>\n\n  <!-- Extract 3 -->\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(38, 198, 218, 0.3); border-radius: 8px; padding: 16px; margin-bottom: 20px; border-left: 4px solid #26C6DA;\">\n    <p style=\"color: #94A3B8; font-style: italic; margin-top: 0; line-height: 1.7;\">\n      <b style=\"color: #26C6DA;\">Read the extract given below and answer the questions that follow:</b><br/>\n      \"The reason the programme has been so successful is because it's impossible to go anywhere near the South Pole and not be affected by it. It's easy to be blase about polar ice-caps melting while sitting in the comfort zone of our respective latitude and longitude, but when you can visibly see glaciers retreating and ice shelves collapsing, you begin to realise that the threat of global warming is very real.\"\n    </p>\n    \n    <p>\n      <b style=\"color: #26C6DA; font-size: 15px;\">Q9: What educational programme is being referred to in this extract?</b><br/>\n      <span style=\"color: #26C6DA; font-weight: bold;\">✓ Answer:</span> Geoff Green's pioneering <b style=\"color: #26C6DA;\">'Students on Ice'</b> programme.\n    </p>\n\n    <p>\n      <b style=\"color: #26C6DA; font-size: 15px;\">Q10: Why are people often nonchalant or blasé about melting polar ice caps?</b><br/>\n      <span style=\"color: #26C6DA; font-weight: bold;\">✓ Answer:</span> Because they observe climate change from the comfortable, detached distance of their temperate home latitudes.\n    </p>\n\n    <p>\n      <b style=\"color: #26C6DA; font-size: 15px;\">Q11: What visible phenomena in Antarctica shock visitors into ecological awareness?</b><br/>\n      <span style=\"color: #26C6DA; font-weight: bold;\">✓ Answer:</span> Visibly watching majestic glaciers retreating and massive Antarctic <b style=\"color: #26C6DA;\">ice shelves collapsing</b> into the ocean.\n    </p>\n\n    <p>\n      <b style=\"color: #26C6DA; font-size: 15px;\">Q12: Who founded the 'Students on Ice' programme, and what was his nationality?</b><br/>\n      <span style=\"color: #26C6DA; font-weight: bold;\">✓ Answer:</span> Canadian educator and expeditionist <b style=\"color: #26C6DA;\">Geoff Green</b>.\n    </p>\n  </div>\n\n  <!-- Extract 4 -->\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(38, 198, 218, 0.3); border-radius: 8px; padding: 16px; margin-bottom: 20px; border-left: 4px solid #26C6DA;\">\n    <p style=\"color: #94A3B8; font-style: italic; margin-top: 0; line-height: 1.7;\">\n      <b style=\"color: #26C6DA;\">Read the extract given below and answer the questions that follow:</b><br/>\n      \"In the parable of the phytoplankton, there is a great metaphor for existence: take care of the small things and the big things will fall into place.\"\n    </p>\n    \n    <p>\n      <b style=\"color: #26C6DA; font-size: 15px;\">Q13: What are phytoplankton, and where do they thrive?</b><br/>\n      <span style=\"color: #26C6DA; font-weight: bold;\">✓ Answer:</span> Single-celled microscopic marine algae that thrive in the upper waters of the Southern Ocean.\n    </p>\n\n    <p>\n      <b style=\"color: #26C6DA; font-size: 15px;\">Q14: What vital biological process do phytoplankton carry out?</b><br/>\n      <span style=\"color: #26C6DA; font-weight: bold;\">✓ Answer:</span> They assimilate carbon and synthesize organic nutrients through <b style=\"color: #26C6DA;\">photosynthesis</b>.\n    </p>\n\n    <p>\n      <b style=\"color: #26C6DA; font-size: 15px;\">Q15: What threat endangers the activity of phytoplankton in Antarctica?</b><br/>\n      <span style=\"color: #26C6DA; font-weight: bold;\">✓ Answer:</span> The depletion of the Antarctic <b style=\"color: #26C6DA;\">ozone layer</b>, exposing them to lethal ultraviolet radiation.\n    </p>\n\n    <p>\n      <b style=\"color: #26C6DA; font-size: 15px;\">Q16: State the universal philosophical and ecological lesson conveyed by this parable.</b><br/>\n      <span style=\"color: #26C6DA; font-weight: bold;\">✓ Answer:</span> Protecting small, microscopic components of an ecosystem automatically safeguards the larger biosphere.\n    </p>\n  </div>\n\n  <!-- SECTION B: SHORT ANSWER QUESTIONS -->\n  <h2 style=\"color: #26C6DA; font-size: 20px; font-weight: 800; border-bottom: 2px solid #26C6DA; padding-bottom: 6px; margin: 30px 0 16px 0;\">\n    SECTION B: Short Answer Questions (3 Marks Each | 40&ndash;50 Words)\n  </h2>\n\n  <!-- Q17 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #26C6DA;\">\n    <h4 style=\"color: #26C6DA; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q17: How did Tishani Doshi reach Antarctica, and what was her initial reaction?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #26C6DA; font-weight: bold;\">✓ Answer:</span> Doshi traveled over one hundred hours from Madras crossing nine time zones, six checkpoints, and three oceans aboard the Russian vessel <i>Akademik Shokalskiy</i>. Her first reaction was profound relief, followed by immense wonder at Antarctica's white isolation and endless horizon.\n    </p>\n  </div>\n\n  <!-- Q18 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #26C6DA;\">\n    <h4 style=\"color: #26C6DA; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q18: What was Gondwana, and what happened to it 650 million years ago?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #26C6DA; font-weight: bold;\">✓ Answer:</span> Gondwana was a giant amalgamated southern supercontinent centred around present-day Antarctica with a warm climate and rich biodiversity. Around the extinction of dinosaurs, continental drift broke Gondwana into separate landmasses, shaping the modern continents.\n    </p>\n  </div>\n\n  <!-- Q19 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #26C6DA;\">\n    <h4 style=\"color: #26C6DA; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q19: How did the Drake Passage affect Antarctica's climate?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #26C6DA; font-weight: bold;\">✓ Answer:</span> When South America drifted away to join North America, it opened up the <b style=\"color: #26C6DA;\">Drake Passage</b>. This created a cold circumpolar current encircling Antarctica, isolating the continent and keeping it eternally frigid, desolate, and ice-covered.\n    </p>\n  </div>\n\n  <!-- Q20 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #26C6DA;\">\n    <h4 style=\"color: #26C6DA; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q20: Why does the author state that humans have created 'quite a ruckus' in 12,000 years?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #26C6DA; font-weight: bold;\">✓ Answer:</span> In a mere twelve thousand years&mdash;a microsecond in geological time&mdash;uncontrolled human population growth, rampant burning of fossil fuels, and aggressive urbanization have blanketed the Earth with carbon dioxide, triggering global warming and threatening biosphere stability.\n    </p>\n  </div>\n\n  <!-- Q21 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #26C6DA;\">\n    <h4 style=\"color: #26C6DA; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q21: Why did Geoff Green switch from taking celebrities to taking high school students?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #26C6DA; font-weight: bold;\">✓ Answer:</span> Celebrities and wealthy retirees were merely curious tourists who gave nothing back to the planet. Green recognized that high school students are the future policy-makers, possessing the energy and idealism to absorb, learn, and implement environmental action.\n    </p>\n  </div>\n\n  <!-- Q22 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #26C6DA;\">\n    <h4 style=\"color: #26C6DA; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q22: Why is Antarctica described as a giant 'ping-pong ball'?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #26C6DA; font-weight: bold;\">✓ Answer:</span> Antarctica is completely devoid of all human landmarks&mdash;there are no trees, billboards, buildings, or telephone poles. The dazzling, unbroken white expanse of ice causes visitors to lose all earthly perspective of scale, time, and distance.\n    </p>\n  </div>\n\n  <!-- Q23 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #26C6DA;\">\n    <h4 style=\"color: #26C6DA; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q23: What crucial role do microscopic phytoplankton play in the Southern Ocean?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #26C6DA; font-weight: bold;\">✓ Answer:</span> Microscopic single-celled <b style=\"color: #26C6DA;\">phytoplankton</b> carry out photosynthesis using sunlight, assimilating carbon to synthesize organic food that sustains the entire Southern Ocean marine food chain, including krill, fish, seabirds, seals, and whales.\n    </p>\n  </div>\n\n  <!-- Q24 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #26C6DA;\">\n    <h4 style=\"color: #26C6DA; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q24: What is the significance of the phrase 'Take care of the small things'?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #26C6DA; font-weight: bold;\">✓ Answer:</span> It emphasizes that ecological stability depends on tiny organisms. If humanity protects microscopic phytoplankton from ozone depletion, the entire global marine food chain and carbon cycle will automatically remain healthy and protected.\n    </p>\n  </div>\n\n  <!-- Q25 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #26C6DA;\">\n    <h4 style=\"color: #26C6DA; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q25: What memorable experience did Doshi have when walking on the ocean?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #26C6DA; font-weight: bold;\">✓ Answer:</span> When their ship wedged in ice, fifty-two passengers walked across a metre-thick ice sheet with 180 metres of living saltwater beneath. She saw Crabeater seals sunning on ice floes like stray dogs under a banyan tree.\n    </p>\n  </div>\n\n  <!-- Q26 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #26C6DA;\">\n    <h4 style=\"color: #26C6DA; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q26: Why does Doshi say that Antarctica holds the key to Earth's past, present, and future?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #26C6DA; font-weight: bold;\">✓ Answer:</span> Its ancient ice cores preserve half-million-year-old carbon records of Earth's geological past; its melting glaciers display present-day global warming; and its collapsing ice shelves forecast the catastrophic future of rising sea levels.\n    </p>\n  </div>\n\n  <!-- Q27 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #26C6DA;\">\n    <h4 style=\"color: #26C6DA; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q27: How does Doshi contrast her South Indian origins with Antarctica?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #26C6DA; font-weight: bold;\">✓ Answer:</span> As a sun-worshipping South Indian from tropical Madras, spending two weeks in a continent containing ninety percent of the world's ice felt like a chilling circulatory and metabolic shock, challenging her bodily senses and perspective.\n    </p>\n  </div>\n\n  <!-- Q28 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #26C6DA;\">\n    <h4 style=\"color: #26C6DA; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q28: What is the emotional effect of visualising retreating glaciers firsthand?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #26C6DA; font-weight: bold;\">✓ Answer:</span> It shatters intellectual complacency. Seeing enormous ice shelves break and plunge into the ocean transforms climate change from an abstract scientific statistic into a visceral, terrifying reality that demands immediate intervention.\n    </p>\n  </div>\n\n  <!-- SECTION C: LONG ANSWER QUESTIONS -->\n  <h2 style=\"color: #26C6DA; font-size: 20px; font-weight: 800; border-bottom: 2px solid #26C6DA; padding-bottom: 6px; margin: 30px 0 16px 0;\">\n    SECTION C: Long Answer / Thematic Questions (6 Marks Each | 120&ndash;150 Words)\n  </h2>\n\n  <!-- Q29 -->\n  <div style=\"margin-bottom: 22px; background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(38, 198, 218, 0.35); border-radius: 10px; padding: 18px; box-shadow: 0 4px 20px rgba(0,0,0,0.3);\">\n    <h3 style=\"color: #26C6DA; font-size: 17px; margin: 0 0 10px 0; font-weight: 800;\">\n      Q29: \"To visit Antarctica is to be part of that history: to get a grasp of where we've come from and where we could possibly be heading.\" Elaborate.\n    </h3>\n    <p style=\"color: #CBD5E1; line-height: 1.8; margin: 0;\">\n      <b style=\"color: #26C6DA;\">Model Answer:</b><br/>\n      <b>1. Geological Origins &amp; Earth's Past:</b> In 'Journey to the End of the Earth', Tishani Doshi highlights that Antarctica serves as Earth's premier geological time capsule. Six hundred and fifty million years ago, Antarctica was the vibrant core of the supercontinent <b style=\"color: #26C6DA;\">Gondwana</b>. Studying its rock formations and continental drift illuminates how India smashed into Asia to form the Himalayas and how the Drake Passage established the circumpolar current, revealing our planet's ancient evolution.<br/><br/>\n      <b>2. The Present Barometer of Climate Change:</b> At present, Antarctica remains the only continent untouched by human settlements, billboards, or industry, harboring half-million-year-old carbon records locked in its pristine ice cores. Yet, it exhibits the most dramatic evidence of modern global warming. Visitors physically witness retreating glaciers and collapsing ice shelves, confirming that human carbon emissions are destabilizing the cryosphere.<br/><br/>\n      <b>3. The Future Warning:</b> Antarctica provides an ominous forecast of humanity's future. If global temperatures continue to rise, melting Antarctic ice could trigger catastrophic sea-level surges, submerging coastal cities worldwide. Thus, Antarctica holds the indispensable keys to Earth's past, present, and future survival.\n    </p>\n  </div>\n\n  <!-- Q30 -->\n  <div style=\"margin-bottom: 22px; background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(38, 198, 218, 0.35); border-radius: 10px; padding: 18px; box-shadow: 0 4px 20px rgba(0,0,0,0.3);\">\n    <h3 style=\"color: #26C6DA; font-size: 17px; margin: 0 0 10px 0; font-weight: 800;\">\n      Q30: Why is the 'Students on Ice' programme considered an unparalleled educational initiative?\n    </h3>\n    <p style=\"color: #CBD5E1; line-height: 1.8; margin: 0;\">\n      <b style=\"color: #26C6DA;\">Model Answer:</b><br/>\n      <b>1. Shift from Tourism to Purposeful Education:</b> Founded by Canadian educator Geoff Green, 'Students on Ice' represents a paradigm shift in environmental education. Green grew weary of guiding wealthy retirees and curious celebrities who treated Antarctica merely as an exotic bucket-list destination without contributing anything to global sustainability.<br/><br/>\n      <b>2. Investing in Youth as Future Custodians:</b> By taking high school students to Antarctica, Green targets youth at an age when their minds are impressionable, idealistic, and eager to absorb, learn, and act. Encountering retreating glaciers and sunning seals firsthand transforms abstract textbook science into a profound, life-altering experience.<br/><br/>\n      <b>3. Fostering Global Policy Champions:</b> These students will become tomorrow's scientists, policy-makers, and world leaders. By witnessing the fragility of polar ecosystems, the programme instills an enduring environmental conscience, equipping them to enact decisive ecological policies to protect the planet.\n    </p>\n  </div>\n\n  <!-- Q31 -->\n  <div style=\"margin-bottom: 22px; background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(38, 198, 218, 0.35); border-radius: 10px; padding: 18px; box-shadow: 0 4px 20px rgba(0,0,0,0.3);\">\n    <h3 style=\"color: #26C6DA; font-size: 17px; margin: 0 0 10px 0; font-weight: 800;\">\n      Q31: Discuss the ecological significance of phytoplankton in light of the golden rule: 'Take care of the small things and the big things will fall into place.'\n    </h3>\n    <p style=\"color: #CBD5E1; line-height: 1.8; margin: 0;\">\n      <b style=\"color: #26C6DA;\">Model Answer:</b><br/>\n      <b>1. The Microscopic Engine of Marine Life:</b> Phytoplankton are single-celled microscopic algae that populate the upper sunlit layers of the Southern Ocean. Despite their microscopic stature, they perform the monumental ecological task of nourishing the entire southern marine food web through photosynthesis, converting sunlight and carbon into life-giving nutrients.<br/><br/>\n      <b>2. Trophic Cascade of Extinction:</b> Higher marine species&mdash;krill, fish, penguins, seals, and blue whales&mdash;depend directly or indirectly on phytoplankton for sustenance. Scientists warn that further depletion of the Antarctic ozone layer will impair phytoplankton photosynthesis. A collapse at this primary trophic level would trigger a catastrophic cascade, destroying marine fauna and disrupting the global carbon cycle.<br/><br/>\n      <b>3. The Ecological Golden Maxim:</b> Doshi employs the phytoplankton as a profound metaphor for universal ecological balance. Humanity often fixates on saving charismatic megafauna like polar bears or whales while neglecting microscopic foundations. Protecting the smallest links in the ecological chain is the singular guarantee that the macro-biosphere will survive.\n    </p>\n  </div>\n\n  <!-- Q32 -->\n  <div style=\"margin-bottom: 22px; background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(38, 198, 218, 0.35); border-radius: 10px; padding: 18px; box-shadow: 0 4px 20px rgba(0,0,0,0.3);\">\n    <h3 style=\"color: #26C6DA; font-size: 17px; margin: 0 0 10px 0; font-weight: 800;\">\n      Q32: Analyze the impact of human civilization on Earth's climate within the context of geological time.\n    </h3>\n    <p style=\"color: #CBD5E1; line-height: 1.8; margin: 0;\">\n      <b style=\"color: #26C6DA;\">Model Answer:</b><br/>\n      <b>1. Cosmic Time Perspective:</b> Tishani Doshi contextualizes human existence against Earth's 4.5-billion-year history. Human civilization has existed for approximately 12,000 years&mdash;barely a fleeting second on the cosmic clock. Yet, this evolutionary blink of an eye has wrought catastrophic devastation.<br/><br/>\n      <b>2. Ecological Destruction &amp; Anthropocene Crises:</b> Humanity has etched its dominance through explosive population growth, aggressive urbanization, deforestation, and the unbridled burning of fossil fuels. This has wrapped the globe in a suffocating shroud of carbon dioxide, driving rapid global warming, unseasonal weather extremes, and the unprecedented retreat of glaciers worldwide.<br/><br/>\n      <b>3. Critical Reflection:</b> The tragedy lies in human arrogance. Humanity acts as if it owns the planet, forgetting that ecosystems evolved harmoniously over millions of years. Antarctica starkly reminds us of our ecological insignificance and the urgent necessity of restoring balance before our species engineers its own extinction.\n    </p>\n  </div>\n\n  <!-- Q33 -->\n  <div style=\"margin-bottom: 22px; background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(38, 198, 218, 0.35); border-radius: 10px; padding: 18px; box-shadow: 0 4px 20px rgba(0,0,0,0.3);\">\n    <h3 style=\"color: #26C6DA; font-size: 17px; margin: 0 0 10px 0; font-weight: 800;\">\n      Q33: How does the author convey the eerie, surreal atmosphere of Antarctica in the text?\n    </h3>\n    <p style=\"color: #CBD5E1; line-height: 1.8; margin: 0;\">\n      <b style=\"color: #26C6DA;\">Model Answer:</b><br/>\n      <b>1. Sensory Deprivation &amp; Absence of Human Markers:</b> Doshi evokes the uncanny, surreal beauty of Antarctica through striking sensory imagery. Describing the continent as a giant ping-pong ball devoid of human markers, she highlights the complete absence of trees, billboards, and architecture, stripping the visitor of conventional spatial cues.<br/><br/>\n      <b>2. Scale, Silence &amp; Polar Light:</b> The visual scale ranges from the microscopic (midges and mites) to the colossal (blue whales and icebergs as big as countries). The visual landscape is bathed in a perpetual, twenty-four-hour austral summer light, punctuated only by an omnipresent silence broken occasionally by the thunderous roar of an avalanche or a calving ice shelf.<br/><br/>\n      <b>3. Spiritual Reverence:</b> Walking on a frozen ocean over 180 metres of salt water while seals stretch on ice floes, Doshi induces a sense of reverence and cosmic humility, evoking a landscape that belongs purely to the primeval Earth.\n    </p>\n  </div>\n\n  <!-- Q34 -->\n  <div style=\"margin-bottom: 22px; background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(38, 198, 218, 0.35); border-radius: 10px; padding: 18px; box-shadow: 0 4px 20px rgba(0,0,0,0.3);\">\n    <h3 style=\"color: #26C6DA; font-size: 17px; margin: 0 0 10px 0; font-weight: 800;\">\n      Q34: What philosophical questions regarding the future of the human race does the journey leave in the author's mind?\n    </h3>\n    <p style=\"color: #CBD5E1; line-height: 1.8; margin: 0;\">\n      <b style=\"color: #26C6DA;\">Model Answer:</b><br/>\n      <b>1. Contemplating Planetary Cycles:</b> Standing under the midnight sun on Antarctica's ice sheet, Doshi reflects on deep time and cyclical planetary evolution. She contemplates whether Antarctica will ever revert to the warm, tropical greenhouse it was 650 million years ago during the Gondwana era.<br/><br/>\n      <b>2. The Question of Human Survival:</b> The harrowing question that follows is whether the human species will still exist to witness such a transformation, or whether humanity will join the dinosaurs in evolutionary extinction due to self-inflicted ecological collapse.<br/><br/>\n      <b>3. A Ray of Hope:</b> Despite these sobering reflections, Doshi finds immense hope in the young students of 'Students on Ice'. Having witnessed the fragility of polar ice caps firsthand, these idealistic teenagers possess the potential to alter humanity's trajectory and ensure the preservation of our biosphere.\n    </p>\n  </div>\n\n  <!-- SECTION D: NCERT TEXTBOOK EXERCISES -->\n  <h2 style=\"color: #26C6DA; font-size: 20px; font-weight: 800; border-bottom: 2px solid #26C6DA; padding-bottom: 6px; margin: 30px 0 16px 0;\">\n    SECTION D: NCERT Textbook Exercises (Reading With Insight)\n  </h2>\n\n  <!-- NCERT Q1 -->\n  <div style=\"margin-bottom: 18px; background: rgba(15, 23, 42, 0.55); border-left: 4px solid #26C6DA; padding: 14px 16px; border-radius: 6px;\">\n    <h4 style=\"color: #26C6DA; font-size: 15.5px; margin: 0 0 6px 0; font-weight: 700;\">Q35 (NCERT 1): How do geological phenomena help us know about the history of humankind?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #26C6DA; font-weight: bold;\">✓ Answer:</span> Geological phenomena such as continental drift, the fracturing of Gondwana, the opening of the Drake Passage, and mountain formation reveal how Earth evolved over hundreds of millions of years before humans emerged. Furthermore, polar ice cores preserve half-million-year-old carbon records, enabling scientists to track pre-historic climate baselines and measure the alarming pace of human-induced global warming.\n    </p>\n  </div>\n\n  <!-- NCERT Q2 -->\n  <div style=\"margin-bottom: 18px; background: rgba(15, 23, 42, 0.55); border-left: 4px solid #26C6DA; padding: 14px 16px; border-radius: 6px;\">\n    <h4 style=\"color: #26C6DA; font-size: 15.5px; margin: 0 0 6px 0; font-weight: 700;\">Q36 (NCERT 2): What are the indications for the future of humankind?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #26C6DA; font-weight: bold;\">✓ Answer:</span> The indications for humankind's future are severely alarming. The rapid melting of polar ice caps, the collapse of Antarctic ice shelves, expanding ozone depletion, and disrupted phytoplankton photosynthesis warn of catastrophic sea-level rises, submerged coastal nations, unseasonal droughts, and mass ecological disruption unless greenhouse gas emissions are swiftly halted.\n    </p>\n  </div>\n\n  <!-- NCERT Q3 -->\n  <div style=\"margin-bottom: 18px; background: rgba(15, 23, 42, 0.55); border-left: 4px solid #26C6DA; padding: 14px 16px; border-radius: 6px;\">\n    <h4 style=\"color: #26C6DA; font-size: 15.5px; margin: 0 0 6px 0; font-weight: 700;\">Q37 (NCERT 3): 'The world's geological history is trapped in Antarctica.' How is the study of this landmass useful to us?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #26C6DA; font-weight: bold;\">✓ Answer:</span> Antarctica holds ninety percent of Earth's total ice volume and has remained untouched by human civilization, preserving ancient geological strata and pristine air bubbles trapped in ice sheets for over 500,000 years. Studying this continent provides unpolluted data regarding historic carbon cycles, atmospheric evolution, ozone levels, and climate sensitivity, making it our most valuable diagnostic laboratory.\n    </p>\n  </div>\n\n  <!-- NCERT Q4 -->\n  <div style=\"margin-bottom: 18px; background: rgba(15, 23, 42, 0.55); border-left: 4px solid #26C6DA; padding: 14px 16px; border-radius: 6px;\">\n    <h4 style=\"color: #26C6DA; font-size: 15.5px; margin: 0 0 6px 0; font-weight: 700;\">Q38 (NCERT 4): What are Geoff Green's reasons for including high school students in the 'Students on Ice' expedition?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #26C6DA; font-weight: bold;\">✓ Answer:</span> Geoff Green included high school students because he believed that taking wealthy tourists and celebrities yielded no positive contribution to the planet. High school students are at an impressionable age where they are ready to absorb, learn, and act. By exposing future policy-makers to the raw fragility of polar ecosystems, Green sought to build an inspired generation of ecological stewards dedicated to saving our planet.\n    </p>\n  </div>\n\n</div>\n";

